import re, json, requests, pathlib, textwrap
p = pathlib.Path('workspace/inbox/dp1.txt')
s = p.read_text(encoding='utf-8')
url = re.search(r'fetch\("([^"]+)"', s).group(1)
# Extract JSON-like object by finding first { after fetch(url, and matching braces, respecting strings
start = s.find('{', s.find('fetch('))
level=0; in_str=False; esc=False; end=None
for i,ch in enumerate(s[start:], start):
    if in_str:
        if esc:
            esc=False
        elif ch == '\\':
            esc=True
        elif ch == '"':
            in_str=False
    else:
        if ch == '"':
            in_str=True
        elif ch == '{':
            level += 1
        elif ch == '}':
            level -= 1
            if level == 0:
                end = i+1
                break
obj_text = s[start:end]
# It is valid JSON-style quoted keys/strings
obj = json.loads(obj_text)
headers = obj.get('headers', {})
body = obj.get('body', '')
method = obj.get('method','POST')
try:
    r = requests.request(method, url, headers=headers, data=body.encode('utf-8'), timeout=30, allow_redirects=False)
    print('URL:', url)
    print('STATUS:', r.status_code)
    print('REASON:', r.reason)
    print('HEADERS:')
    for k,v in r.headers.items():
        print(f'{k}: {v}')
    print('\nBODY_PREVIEW:')
    print(r.text[:4000])
except Exception as e:
    print('ERROR:', type(e).__name__, str(e))

